## Code Example

```javascript
// Lightweight feature extraction prototype
function extractFeatures(text) {
  const t = text.toLowerCase()
    .replace(/https?:\/\/\S+/g, 'URL')
    .replace(/\s+/g, ' ')
    .trim();
  const ngrams = {};
  for (let i = 0; i < t.length - 2; i++) {
    const ng = t.slice(i, i + 3);
    ngrams[ng] = (ngrams[ng] || 0) + 1;
  }
  return ngrams;
}
```

